// Generates lib/snack_beats/levels_data.g.dart (200 levels, moves calibrated by robot play-tests).
// Run from packages/snack_beats_game:  dart run tool/generate_levels.dart [count]
import 'dart:io';

import 'package:snack_beats_game/snack_beats/engine/level_gen.dart';

void main(List<String> args) {
  final count = args.isNotEmpty ? int.parse(args.first) : 200;
  final sw = Stopwatch()..start();
  final out = StringBuffer()
    ..writeln(
      '// GENERATED by tool/generate_levels.dart — do not edit by hand.',
    )
    ..writeln(
      '// Moves were calibrated by robot play-tests (80% of beginner games finish in time).',
    )
    ..writeln('// ignore_for_file: lines_longer_than_80_chars')
    ..writeln("import 'engine/level_gen.dart';")
    ..writeln()
    ..writeln('const levelData = <LevelData>[');
  final shapeCount = <String, int>{};
  for (var i = 0; i < count; i++) {
    final l = calibrate(i);
    shapeCount[l.shape] = (shapeCount[l.shape] ?? 0) + 1;
    final layout = l.layout.map((r) => "'$r'").join(', ');
    final goals = l.goals.map((g) => '[${g[0]}, ${g[1]}]').join(', ');
    out.writeln(
      "  LevelData(shape: '${l.shape}', nTypes: ${l.nTypes}, moves: ${l.moves}, goals: [$goals], layout: [$layout]), // ${i + 1}",
    );
    if ((i + 1) % 20 == 0) {
      stdout.writeln(
        'levels ${i + 1}/$count  (${(sw.elapsedMilliseconds / 1000).toStringAsFixed(1)}s)',
      );
    }
  }
  out.writeln('];');
  File('lib/snack_beats/levels_data.g.dart').writeAsStringSync(out.toString());
  stdout.writeln(
    'done in ${(sw.elapsedMilliseconds / 1000).toStringAsFixed(1)}s; shapes: $shapeCount',
  );
}
